G=[a for a in itertools.product(range(5),repeat=4) if (a[0]*a[3]-a[1]*a[2])%5==1]; idx={g:i for i,g in enumerate(G)}; n=len(G)
def mul(a,b):
 A,B,C,D=a; e,f,g,h=b
 return ((A*e+B*g)%5,(A*f+B*h)%5,(C*e+D*g)%5,(C*f+D*h)%5)
